ALTER TABLE BZA_BOOTSTRAP_APPROVAL
    ADD COLUMN CLAIM_OWNER_ID VARCHAR(100) NULL AFTER CLAIMED_AT,
    ADD COLUMN CLAIM_EXPIRES_AT DATETIME(6) NULL AFTER CLAIM_OWNER_ID,
    ADD COLUMN CLEANUP_STATUS VARCHAR(20) NOT NULL DEFAULT 'PENDING' AFTER FAILURE_CODE,
    ADD COLUMN CLEANUP_FAILURE_CODE VARCHAR(100) NULL AFTER CLEANUP_STATUS,
    ADD COLUMN CLEANUP_UPDATED_AT DATETIME(6) NULL AFTER CLEANUP_FAILURE_CODE,
    ADD CONSTRAINT CK_BZA_BOOTSTRAP_CLEANUP_STATUS
        CHECK (CLEANUP_STATUS IN ('PENDING','COMPLETED','FAILED'));

CREATE INDEX IX_BZA_BOOTSTRAP_CLAIM_LEASE
    ON BZA_BOOTSTRAP_APPROVAL(STATUS, CLAIM_EXPIRES_AT);
